package org.pbinitiative.zenbpmadapter.client;

import java.util.Locale;
import java.util.Optional;
import java.util.ResourceBundle;
import java.util.regex.Pattern;

import com.google.protobuf.RuntimeVersion;

/**
 * Whether the protobuf runtime an application resolves can run the job stream's classes.
 * <p>
 * Those classes were generated by a <code>protoc</code> of the version of the protobuf runtime
 * this adapter is built against, and protobuf refuses to load them on a runtime older than that
 * <code>protoc</code>. An application whose own dependencies bring an older
 * <code>com.google.protobuf:protobuf-java</code> would otherwise fail with protobuf's own error at
 * the first job stream class it touches, which names neither this adapter nor the version to
 * raise to. So the platforms run this check while the application starts (Spring Boot) or while
 * it is built (Quarkus), and the job stream runs it again before it touches a generated class.
 * <p>
 * The check asks protobuf itself, with the same call the generated classes make when they load,
 * so its answer follows protobuf's rules and not a copy of them.
 */
public final class ProtobufRuntimeCheck {

    /**
     * The dependency an application raises where the check fails.
     */
    static final String DEPENDENCY = "com.google.protobuf:protobuf-java";

    private static final String BUNDLE = "META-INF/vanillabp/adapter-zenbpm";

    private static final String GENCODE_VERSION_KEY = "protobuf.gencode";

    /**
     * The versions <code>protoc</code> writes into the classes it generates: three numbers and a
     * suffix such as <code>-rc1</code>, which a release does not have.
     */
    private static final Pattern VERSION = Pattern.compile("(\\d+)\\.(\\d+)\\.(\\d+)(.*)");

    private ProtobufRuntimeCheck() {
    }

    /**
     * Why the protobuf runtime of this application cannot run the job stream.
     *
     * @return The guiding message, empty where the runtime can run it
     */
    public static Optional<String> defect() {
        return defect(gencodeVersion());
    }

    /**
     * Refuses a protobuf runtime which cannot run the job stream.
     *
     * @throws IllegalStateException With the message of {@link #defect()}
     */
    public static void requireCompatibleRuntime() {
        requireCompatibleRuntime(gencodeVersion());
    }

    /**
     * Refuses a protobuf runtime which cannot run classes generated by a given
     * <code>protoc</code>.
     *
     * @param gencodeVersion The version of the <code>protoc</code>, e.g. <code>4.35.0</code>
     * @throws IllegalStateException With the message of {@link #defect(String)}
     */
    static void requireCompatibleRuntime(final String gencodeVersion) {
        final var defect = defect(gencodeVersion);
        if (defect.isPresent()) {
            throw new IllegalStateException(defect.get());
        }
    }

    /**
     * Why the protobuf runtime of this application cannot run classes generated by a given
     * <code>protoc</code>.
     *
     * @param gencodeVersion The version of the <code>protoc</code>, e.g. <code>4.35.0</code>
     * @return The guiding message, empty where the runtime can run them
     */
    static Optional<String> defect(final String gencodeVersion) {
        final var version = VERSION.matcher(gencodeVersion);
        if (!version.matches()) {
            throw new IllegalStateException(
                    "'%s' of '%s.properties' is '%s' instead of a protobuf version, so the adapter's jar is broken. The resource is filtered from 'protobuf.version' of the adapter's root POM."
                            .formatted(GENCODE_VERSION_KEY, BUNDLE, gencodeVersion));
        }
        final var major = Integer.parseInt(version.group(1));
        final var minor = Integer.parseInt(version.group(2));
        final var patch = Integer.parseInt(version.group(3));
        try {
            RuntimeVersion.validateProtobufGencodeVersion(RuntimeVersion.RuntimeDomain.PUBLIC, major, minor, patch,
                    version.group(4), "the job stream of the ZenBPM adapter");
            return Optional.empty();
        } catch (final LinkageError missing) {
            // a runtime older than 4.26.0 has no RuntimeVersion, and the generated classes fail
            // on that first. The name is written out: the class literal would fail the same way.
            return Optional.of(message(gencodeVersion,
                    "The protobuf runtime of the application has no 'com.google.protobuf.RuntimeVersion' (%s), so it is older than 4.26.0."
                            .formatted(missing)));
        } catch (final RuntimeException refusal) {
            // protobuf's own exception, which names both versions. Its class is not named here:
            // a runtime without it would fail this class while loading it, not answer the check.
            return Optional.of(message(gencodeVersion, refusal.getMessage()));
        }
    }

    private static String message(
        final String gencodeVersion,
        final String reason
    ) {
        return """
                %s The job stream of the ZenBPM adapter was generated for protobuf %s and needs '%s' in version %s or \
                a later version of the same major version. Raise '%s' to %s or later in the dependency management of \
                the application; a framework's BOM may pin an older one."""
                .formatted(reason, gencodeVersion, DEPENDENCY, gencodeVersion, DEPENDENCY, gencodeVersion);
    }

    /**
     * The version of the <code>protoc</code> which generated the job stream's classes, filtered
     * into the adapter's jar by the build. A jar without it is broken, and the
     * <code>MissingResourceException</code> names what is missing.
     */
    private static String gencodeVersion() {
        return ResourceBundle
                .getBundle(BUNDLE, Locale.ROOT)
                .getString(GENCODE_VERSION_KEY);
    }

}
